-- ---------------------------------------------------------------------------------------------
-- A customer and its first contact can be created in one transaction and made primary there.
ALTER TABLE "customers" ALTER CONSTRAINT "customers_primary_contact_fkey" DEFERRABLE INITIALLY DEFERRED;

-- Integrity checks that hold whatever code writes.
ALTER TABLE "customers"
  ADD CONSTRAINT customers_display_name_length CHECK (char_length(btrim("display_name")) BETWEEN 1 AND 200),
  ADD CONSTRAINT customers_country_format CHECK ("country_code" IS NULL OR "country_code" ~ '^[A-Z]{2}$'),
  ADD CONSTRAINT customers_email_lower CHECK ("email" IS NULL OR "email" = lower("email"));
ALTER TABLE "contacts"
  ADD CONSTRAINT contacts_display_name_length CHECK (char_length(btrim("display_name")) BETWEEN 1 AND 200),
  ADD CONSTRAINT contacts_email_lower CHECK ("email" IS NULL OR "email" = lower("email"));
ALTER TABLE "activities"
  -- A user activity names its user; a system activity names none (data-model §4.7).
  ADD CONSTRAINT activities_actor_consistent CHECK (
    ("actor_type" = 'USER' AND "actor_user_id" IS NOT NULL) OR ("actor_type" = 'SYSTEM' AND "actor_user_id" IS NULL) OR "actor_type" = 'AI'),
  ADD CONSTRAINT activities_type_format CHECK ("type" ~ '^[a-z][a-z_]*(\.[a-z_]+)*$' AND char_length("type") <= 64);

-- ---------------------------------------------------------------------------------------------
-- Least privilege for tenant code. No DELETE: archiving is reversible and hard deletion (erasure)
-- arrives with its own reviewed path. bos_owner's default privileges are revoked first.
REVOKE ALL ON "customers", "contacts", "activities" FROM bos_app;
GRANT SELECT, INSERT, UPDATE ON "customers", "contacts" TO bos_app;
GRANT SELECT, INSERT ON "activities" TO bos_app;
GRANT UPDATE ("deleted_at", "updated_at") ON "activities" TO bos_app;

-- Tenant policy template (§5.2), forced so the table owner is subject to it too.
ALTER TABLE "customers" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "customers" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "customers" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "contacts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "contacts" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "contacts" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "activities" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "activities" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "activities" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
